<template>
  <el-dialog title="平台换货详情" :visible.sync="visible" width="92%" append-to-body :close-on-click-modal="false">
    <div v-loading="loading" v-if="row">
      <div class="identity"><div><strong>{{ row.dispute_id }}</strong><el-button v-clipboard:copy="row.dispute_id" type="text" icon="el-icon-document-copy" aria-label="复制平台换货单号" /><p>平台主单 {{ row.platform_tid || '待关联' }} · 平台子单 {{ row.platform_oid || '未提供' }}</p><p>{{ row.order_sn || '原 OMS 订单待关联' }} · {{ phases[row.source_phase] }} · {{ row.speed_exchange==null?'类型待确认':Number(row.speed_exchange)===1?'极速换货':'普通换货' }}</p></div><div class="right"><el-tag>{{ platforms[row.platform_status] || row.platform_status || '平台状态待核对' }}</el-tag><p>{{ deadline(row) }}</p></div></div>
      <el-alert v-if="row.source_error || row.conversion_error" :title="row.source_error || row.conversion_error" type="warning" :closable="false" show-icon />
      <div class="summary"><article><span>平台最新申请</span><strong>{{ row.requested_quantity }} 件</strong><p>{{ row.original_description || '原规格未提供' }} → {{ row.target_description || '目标规格未提供' }}</p></article><article><span>来源资料</span><strong>{{ sourceStates[row.source_state] }}</strong><p>来源版本 {{ row.version }} · 修改于 {{ row.source_modified || '未提供' }}</p><p>最近同步 {{ row.last_sync }}</p></article><article><span>业务转单</span><strong>{{ conversionStates[row.conversion_state] }}</strong><p>{{ row.exchange_sn || '尚未生成业务换货单' }}</p><p>{{ states[row.business_state] }}</p></article></div>
      <message-progress v-if="row.message" :message="row.message" type="EXCHANGE_CONVERT"/><p v-if="row.refresh_task" class="hint">平台资料更新任务 #{{ row.refresh_task }} 已提交，完成后请刷新详情。<el-button type="text" @click="refreshTask">查看同步进度</el-button></p>
      <div class="actions"><el-button v-if="!row.business_exchange_id && row.conversion_state!=='SKIPPED'" v-hasPermi="['order:exchange:review']" type="primary" size="small" :loading="busy" @click="convert">{{ row.conversion_state==='FAILED'?'重试转业务换货单':'转业务换货单' }}</el-button><el-button v-if="!row.business_exchange_id && row.conversion_state!=='SKIPPED'" v-hasPermi="['order:exchange:review']" size="small" @click="prepareLink">关联已有协商单</el-button><el-button v-if="row.business_exchange_id" v-hasPermi="['order:exchange:query']" type="primary" size="small" @click="business">查看业务换货</el-button><el-button v-hasPermi="['order:exchange:sync']" size="small" :loading="busy" @click="refreshPlatform">更新平台资料</el-button><platform-log-link :number="row.dispute_id" number-type="PLATFORM_EXCHANGE" /></div>
      <p class="hint">转单只生成或关联 HH；审核、平台同意、仓库出入库分别执行。更新平台资料进入后台查询队列；刷新详情只读取本地资料。</p>
      <el-tabs v-model="tab">
        <el-tab-pane label="业务关联与审核方案" name="business"><template v-if="row.business_exchange_id"><p v-if="row.business_kind==='INTERNAL'" class="warning">已复用客服协商单的履约；平台同意、拒绝与物流结果仍需人工核对。</p><el-descriptions :column="2" border size="small"><el-descriptions-item label="业务换货单">{{ row.exchange_sn }}</el-descriptions-item><el-descriptions-item label="业务状态">{{ states[row.business_state] }}</el-descriptions-item><el-descriptions-item label="OMS 目标 SKU">{{ row.target_sku || '待审核确认' }}</el-descriptions-item><el-descriptions-item label="原 OMS 订单">{{ row.order_sn }}</el-descriptions-item></el-descriptions><template v-if="row.approved_version"><h4>平台最新资料与已审核方案</h4><el-alert :title="row.adopted.same_source?'审核采用来源与当前平台资料一致':'平台来源与审核采用来源不同，请在业务换货中核对是否影响方案；已执行事实保留'" :type="row.adopted.same_source?'success':'warning'" :closable="false" /><el-table :data="comparison"><el-table-column prop="name" label="项目" width="160" /><el-table-column prop="latest" label="平台最新申请" min-width="240" /><el-table-column prop="adopted" label="业务已审核方案" min-width="240" /></el-table><p class="hint">审核人 {{ row.adopted.review_by }} · {{ row.adopted.reviewed_at }}</p></template><el-empty v-else description="业务单尚未审核，目标 SKU 及实际履约来源需在业务换货中确认" :image-size="65" /></template><el-empty v-else :description="row.conversion_error || '先关联原订单，再自动或人工转业务换货单'" :image-size="65" /></el-tab-pane>
        <el-tab-pane label="来源版本与变更" name="versions"><p class="hint">当前展示最近30份不同内容的来源快照；重复查询相同内容保留原快照，不新增版本。原文按权限查看。</p><el-table :data="row.snapshots"><el-table-column label="收到时间 / 来源" width="175"><template slot-scope="s">{{ s.row.create_time }}<div class="hint">{{ s.row.actor }}</div></template></el-table-column><el-table-column prop="source_modified" label="平台修改时间" width="175" /><el-table-column label="识别结果" width="120"><template slot-scope="s">{{ outcomes[s.row.outcome] || s.row.outcome }}</template></el-table-column><el-table-column label="变更字段" min-width="300"><template slot-scope="s"><span>{{ differences(s.row).map(d=>fields[d.field]||d.field).join('、') || '无业务字段变化' }}</span><el-button v-if="differences(s.row).length" type="text" @click="showChanges(s.row)">查看差异</el-button></template></el-table-column><el-table-column label="操作" width="130"><template slot-scope="s"><el-button v-hasPermi="['order:exchange:raw']" type="text" @click="snapshot(s.row)">查看本次原文</el-button></template></el-table-column></el-table></el-tab-pane>
        <el-tab-pane label="平台物流" name="logistics"><p class="hint">以下为平台提供的物流信息；实际收货、出库和库存记账请到业务换货核对。</p><el-descriptions :column="2" border><el-descriptions-item label="买家寄回承运商">{{ row.logistics.buyer_carrier || '未提供' }}</el-descriptions-item><el-descriptions-item label="买家寄回运单">{{ row.logistics.buyer_no || '未提供' }}</el-descriptions-item><el-descriptions-item label="卖家换出承运商">{{ row.logistics.seller_carrier || '未提供' }}</el-descriptions-item><el-descriptions-item label="卖家换出运单">{{ row.logistics.seller_no || '未提供' }}</el-descriptions-item></el-descriptions></el-tab-pane>
        <el-tab-pane label="同步与交互记录" name="tasks"><p class="hint">最近20次关联任务；平台接口请求与响应请通过平台交互日志查询。</p><el-table :data="row.tasks"><el-table-column prop="task_id" label="同步任务" width="130" /><el-table-column prop="create_time" label="发起时间" width="180" /><el-table-column label="读取结果" width="130"><template slot-scope="s">{{ outcomes[s.row.result] || s.row.result }}</template></el-table-column><el-table-column prop="message" label="说明" min-width="300" /></el-table><el-button type="text" @click="tasks">进入统一同步任务</el-button><platform-log-link :number="row.dispute_id" number-type="PLATFORM_EXCHANGE" /></el-tab-pane>
      </el-tabs>
    </div>
    <span slot="footer"><el-button :disabled="busy || !row" :loading="loading" @click="open(row.id)">刷新详情</el-button><el-button :disabled="busy" @click="visible=false">关闭</el-button></span>
    <el-dialog title="关联已有协商换货" :visible.sync="linkVisible" width="760px" append-to-body :close-on-click-modal="false"><el-alert title="关联后沿用原协商单，不重复创建履约。请核对商品规格、申请数量和实际发货来源一致。" type="warning" :closable="false" /><el-form label-width="120px" style="margin-top:20px"><el-form-item label="原协商单"><el-select v-model="linkId" style="width:100%" placeholder="同一原单、子单及数量的未关联协商单"><el-option v-for="r in candidates" :key="r.id" :value="r.id" :label="`${r.exchange_sn} · ${r.target_sku || 'SKU待确认'} · ${r.requested_quantity}件`" /></el-select><p class="hint">最多显示最近50张候选；没有候选时请先核对原订单和申请数量。</p><router-link v-if="linkId" :to="{path:'/oms-order/exchanges',query:{exchangeId:linkId}}" target="_blank">打开原协商单，核对实际商品与履约来源</router-link></el-form-item><el-form-item label="核对依据"><el-input v-model="reason" type="textarea" maxlength="500" /></el-form-item><el-form-item><el-checkbox v-model="confirmed">已核对本次平台版本、商品规格、数量及履约来源一致</el-checkbox></el-form-item></el-form><span slot="footer"><el-button :disabled="busy" @click="linkVisible=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!linkId || !reason.trim() || !confirmed" @click="link">确认关联</el-button></span></el-dialog>
    <el-dialog title="平台换货来源原文" :visible.sync="rawVisible" width="85%" append-to-body><pre class="raw">{{ raw }}</pre></el-dialog>
    <el-dialog title="本次来源变更" :visible.sync="changesVisible" width="800px" append-to-body><el-table :data="changes"><el-table-column label="字段" width="160"><template slot-scope="s">{{ fields[s.row.field] || s.row.field }}</template></el-table-column><el-table-column prop="before" label="原值" min-width="240" /><el-table-column prop="after" label="新值" min-width="240" /></el-table></el-dialog>
  </el-dialog>
</template>
<script>
import * as api from '@/api/order/platformExchange'
import PlatformLogLink from '@/views/oms/channel/PlatformLogLink'
import MessageProgress from '@/views/oms/messaging/MessageProgress'
import { platforms, states } from './exchangeLabels'
import { conversionStates, sourceStates, phases, outcomes, fields, deadline } from './platformExchangeLabels'
export default { name:'PlatformExchangeDetail',components:{PlatformLogLink,MessageProgress},data:()=>({visible:false,loading:false,busy:false,row:null,tab:'business',sequence:0,rawVisible:false,raw:'',linkVisible:false,candidates:[],linkId:null,reason:'',confirmed:false,changesVisible:false,changes:[],platforms,states,conversionStates,sourceStates,phases,outcomes,fields}),computed:{comparison(){const r=this.row,a=r.adopted||{};return[{name:'申请数量',latest:`${r.requested_quantity} 件`,adopted:`${a.quantity} 件`},{name:'平台目标规格',latest:r.target_description||'—',adopted:a.target_description||'—'},{name:'OMS 目标 SKU',latest:'由业务审核确认',adopted:a.target_sku||'—'},{name:'平台修改时间',latest:r.source_modified,adopted:a.source_modified}]}},methods:{deadline,async open(id){const seq=++this.sequence;this.visible=true;this.loading=true;this.row=null;this.tab='business';try{const r=(await api.platformExchangeDetail(id)).data;if(seq===this.sequence)this.row=r}finally{if(seq===this.sequence)this.loading=false}},async convert(){if(this.busy)return;this.busy=true;try{const r=(await api.platformExchangeConvert(this.row.id)).data;this.$message[['SUCCESS','PENDING'].includes(r.state)?'success':'warning'](r.state==='SUCCESS'?'已转业务换货单，待业务审核':r.message||'本申请无需转单');await this.open(this.row.id);this.$emit('changed')}finally{this.busy=false}},async refreshPlatform(){if(this.busy)return;this.busy=true;try{this.row=(await api.platformExchangeRefresh(this.row.id)).data;this.$message.success('已提交平台资料更新，请从同步进度查看结果');this.$emit('changed')}finally{this.busy=false}},business(){this.visible=false;this.$router.push({path:'/oms-order/exchanges',query:{exchangeId:this.row.business_exchange_id}})},refreshTask(){this.visible=false;this.$router.push({path:'/oms-order/syncTasks',query:{tab:'tasks',kind:'EXCHANGE',taskId:this.row.refresh_task}})},tasks(){this.visible=false;this.$router.push({path:'/oms-order/syncTasks',query:{tab:'tasks',kind:'EXCHANGE'}})},differences(r){try{return typeof r.difference_json==='string'?JSON.parse(r.difference_json):r.difference_json||[]}catch(_){return[]}},showChanges(r){this.changes=this.differences(r);this.changesVisible=true},async snapshot(r){const d=(await api.platformExchangeSnapshot(this.row.id,r.id)).data;this.raw=typeof d.payload==='string'?JSON.stringify(JSON.parse(d.payload),null,2):JSON.stringify(d.payload,null,2);this.rawVisible=true},async prepareLink(){this.candidates=(await api.platformExchangeCandidates(this.row.id)).data;this.linkId=null;this.reason='';this.confirmed=false;this.linkVisible=true},async link(){if(this.busy)return;this.busy=true;try{await api.platformExchangeLink(this.row.id,{version:this.row.version,exchange_id:this.linkId,reason:this.reason,confirmed:this.confirmed});this.linkVisible=false;await this.open(this.row.id);this.$emit('changed');this.$message.success('已关联原协商单，沿用原履约')}finally{this.busy=false}}} }
</script>
<style scoped>.identity{display:flex;justify-content:space-between;gap:24px;padding:20px;background:#f4f7fc;margin-bottom:16px;line-height:1.7}.identity strong{font-size:20px}.identity p{margin:6px 0;color:#718098}.right{text-align:right}.summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:20px 0}.summary article{padding:18px;border:1px solid #e4eaf2;border-radius:6px;line-height:1.8;overflow-wrap:anywhere}.summary span,.hint{color:#8290a4;font-size:12px;line-height:1.8}.summary strong{display:block;font-size:18px;color:#34445e;margin:5px 0}.summary p{margin:4px 0}.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.actions .el-button{margin-left:0}.warning{color:#b77515;line-height:1.8}.raw{white-space:pre-wrap;word-break:break-all;max-height:65vh;overflow:auto}h4{margin:24px 0 14px}</style>
